#!/usr/bin/env python3
"""Analyze JSONL data: compute statistics, group by categories, and generate a summary report."""

import json
import sys
import math
from collections import defaultdict


def load_jsonl(path):
    """Load records from a JSONL file."""
    records = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records


def mean(values):
    return sum(values) / len(values)


def median(values):
    s = sorted(values)
    n = len(s)
    mid = n // 2
    if n % 2 == 0:
        return (s[mid - 1] + s[mid]) / 2
    return s[mid]


def std_dev(values):
    m = mean(values)
    variance = sum((v - m) ** 2 for v in values) / len(values)
    return math.sqrt(variance)


def compute_stats(values):
    """Return a dict of statistics for a list of numbers."""
    if not values:
        return {}
    return {
        "count": len(values),
        "mean": round(mean(values), 4),
        "median": round(median(values), 4),
        "std_dev": round(std_dev(values), 4),
        "min": min(values),
        "max": max(values),
    }


def find_numeric_fields(records):
    """Identify fields that contain numeric values."""
    numeric_fields = set()
    for rec in records:
        for k, v in rec.items():
            if isinstance(v, (int, float)):
                numeric_fields.add(k)
    return sorted(numeric_fields)


def find_category_fields(records):
    """Identify fields that contain string values (potential categories)."""
    cat_fields = set()
    for rec in records:
        for k, v in rec.items():
            if isinstance(v, str):
                cat_fields.add(k)
    return sorted(cat_fields)


def group_by(records, field):
    """Group records by a category field."""
    groups = defaultdict(list)
    for rec in records:
        key = rec.get(field, "<missing>")
        groups[key].append(rec)
    return dict(groups)


def analyze(records, category_field=None, numeric_field=None):
    """
    Analyze records. If category_field is given, group by it.
    If numeric_field is given, compute stats on that field; otherwise
    compute stats on all numeric fields.
    """
    numeric_fields = find_numeric_fields(records)
    targets = [numeric_field] if numeric_field else numeric_fields

    if category_field:
        groups = group_by(records, category_field)
    else:
        groups = {"<all>": records}

    report = {
        "total_records": len(records),
        "category_field": category_field,
        "groups": {},
    }

    for group_name, group_records in sorted(groups.items()):
        group_stats = {}
        for nf in targets:
            values = [r[nf] for r in group_records if nf in r and isinstance(r.get(nf), (int, float))]
            if values:
                group_stats[nf] = compute_stats(values)
        report["groups"][group_name] = {
            "count": len(group_records),
            "stats": group_stats,
        }

    return report


def format_report(report):
    """Format the report dict as a readable string."""
    lines = []
    lines.append("=" * 60)
    lines.append("  JSONL Analysis Report")
    lines.append("=" * 60)
    lines.append(f"  Total records: {report['total_records']}")
    if report["category_field"]:
        lines.append(f"  Grouped by:    {report['category_field']}")
    lines.append("")

    for group_name, group_data in report["groups"].items():
        lines.append(f"--- {group_name} ({group_data['count']} records) ---")
        if not group_data["stats"]:
            lines.append("  (no numeric fields found)")
        for field, stats in group_data["stats"].items():
            lines.append(f"  [{field}]")
            for k, v in stats.items():
                lines.append(f"    {k:>8}: {v}")
        lines.append("")

    lines.append("=" * 60)
    return "\n".join(lines)


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <data.jsonl> [category_field] [numeric_field]")
        print()
        print("  data.jsonl       Path to JSONL file")
        print("  category_field   Optional field to group by (string fields)")
        print("  numeric_field    Optional specific numeric field to analyze")
        sys.exit(1)

    path = sys.argv[1]
    category_field = sys.argv[2] if len(sys.argv) > 2 else None
    numeric_field = sys.argv[3] if len(sys.argv) > 3 else None

    records = load_jsonl(path)
    if not records:
        print("No records found.")
        sys.exit(1)

    print(f"\nLoaded {len(records)} records from {path}")
    print(f"Numeric fields: {find_numeric_fields(records)}")
    print(f"Category fields: {find_category_fields(records)}\n")

    report = analyze(records, category_field, numeric_field)
    print(format_report(report))


if __name__ == "__main__":
    main()
